contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance");

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint cEtherBefore = address(c).balance;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint callerBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfter = address(c).balance;

        assert(callerBalance >= depositAmount && cEtherAfter == cEtherBefore + depositAmount);
    }

    receive() external payable {}
}

